            t, _ = peek()
            if t == '*':
                pos += 1
                val *= parse_unary()
            elif t == '/':
                pos += 1
                rhs = parse_unary()
                val = trunc_div(val, rhs)
            else:
                break
        return val

    def parse_unary():
        nonlocal pos
        t, _ = peek()
        if t == '-':
            pos += 1
            return -parse_unary()
        return parse_primary()

    def parse_primary():
        nonlocal pos
        t, v = peek()
        if t == 'NUM':
            pos += 1
            return v
        if t == '(':
            pos += 1
            val = parse_expr()
            t2, _ = peek()
            if t2 != ')':
                raise ValueError("Expected closing parenthesis")
            pos += 1
            return val
        raise ValueError(f"Unexpected token: {t}")

